<?php
/**
 * Site editor in wp-admin experiment.
 *
 * Shows the extensible site editor inside wp-admin, using the
 * `site-editor-v2-wp-admin` page generated by `@wordpress/build`, and lists its
 * sections under Appearance in the admin menu. Only loaded while both the
 * `gutenberg-extensible-site-editor` and `gutenberg-site-editor-wp-admin`
 * experiments are enabled (see lib/load.php).
 *
 * @package gutenberg
 */

// This experiment replaces the Appearance menu item pointing at the
// fullscreen extensible site editor.
remove_action( 'admin_menu', 'gutenberg_redirect_to_extensible_site_editor', 100 );

/**
 * Returns the URL of the site editor page inside wp-admin, relative to the
 * admin URL.
 *
 * @param string $path Optional. Route path to open.
 * @return string The page URL.
 */
function gutenberg_get_site_editor_wp_admin_url( $path = '/' ) {
	$url = 'themes.php?page=site-editor-v2-wp-admin';
	if ( '/' !== $path ) {
		$url .= '&p=' . $path;
	}
	return $url;
}

/**
 * Returns the site editor sections listed in the admin menu.
 *
 * Home is left out because the page's own Editor item opens it, and Pages is
 * left out because the top-level Pages menu already covers it.
 *
 * @return array[] List of sections, see gutenberg_get_site_editor_sections().
 */
function gutenberg_get_site_editor_wp_admin_sections() {
	return array_values(
		array_filter(
			gutenberg_get_site_editor_sections(),
			static function ( $section ) {
				return ! in_array( $section['id'], array( 'home', 'pages' ), true );
			}
		)
	);
}

/**
 * Registers the site editor page under Appearance, and replaces Core's site
 * editor submenu items with one item per site editor section.
 *
 * @global array $submenu WordPress admin submenu array.
 */
function gutenberg_register_site_editor_wp_admin_menu() {
	global $submenu;

	if ( empty( $submenu['themes.php'] ) ) {
		return;
	}

	// Core only adds site editor items (Editor, Patterns, Template Parts) when
	// the theme supports them, so use their presence as the gate.
	$insert_at = null;
	foreach ( $submenu['themes.php'] as $key => $item ) {
		if ( isset( $item[2] ) && str_starts_with( $item[2], 'site-editor.php' ) ) {
			if ( null === $insert_at ) {
				$insert_at = $key;
			}
			unset( $submenu['themes.php'][ $key ] );
		}
	}

	if ( null === $insert_at ) {
		return;
	}

	$hook_suffix = add_submenu_page(
		'themes.php',
		__( 'Site Editor', 'gutenberg' ),
		__( 'Editor', 'gutenberg' ),
		'edit_theme_options',
		'site-editor-v2-wp-admin',
		'gutenberg_site_editor_v2_wp_admin_render_page'
	);

	if ( $hook_suffix ) {
		add_action( "load-$hook_suffix", 'gutenberg_site_editor_wp_admin_prepare_screen' );
	}

	// `add_submenu_page()` appends the item; move it to where Core's Editor
	// item was, followed by the other sections.
	$editor_item = array_pop( $submenu['themes.php'] );
	$new_items   = array( $editor_item );
	foreach ( gutenberg_get_site_editor_wp_admin_sections() as $section ) {
		$new_items[] = array(
			$section['label'],
			'edit_theme_options',
			gutenberg_get_site_editor_wp_admin_url( $section['to'] ),
			$section['label'],
		);
	}

	$reordered = array();
	foreach ( $submenu['themes.php'] as $key => $item ) {
		if ( $key > $insert_at && ! empty( $new_items ) ) {
			array_push( $reordered, ...$new_items );
			$new_items = array();
		}
		$reordered[] = $item;
	}
	array_push( $reordered, ...$new_items );

	$submenu['themes.php'] = $reordered; // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited
}
add_action( 'admin_menu', 'gutenberg_register_site_editor_wp_admin_menu', 100 );

/**
 * Returns the admin menu section matching a route path.
 *
 * Uses the longest of the section's `to` path and its `match_prefixes` that
 * the route path equals or starts with, followed by a `/`.
 *
 * @param string $path Route path, as in the `p` query arg.
 * @return array|null The section, or null when none matches.
 */
function gutenberg_get_site_editor_wp_admin_section_for_path( $path ) {
	$path     = '/' . trim( explode( '?', $path )[0], '/' );
	$best     = null;
	$best_len = 0;

	foreach ( gutenberg_get_site_editor_wp_admin_sections() as $section ) {
		$prefixes = array_merge( array( $section['to'] ), $section['match_prefixes'] ?? array() );
		foreach ( $prefixes as $prefix ) {
			$matches = $path === $prefix || str_starts_with( $path, $prefix . '/' );
			if ( $matches && strlen( $prefix ) > $best_len ) {
				$best     = $section;
				$best_len = strlen( $prefix );
			}
		}
	}

	return $best;
}

/**
 * Sets the highlighted menu item before wp-admin/admin-header.php renders.
 * Routes that don't belong to a section highlight Editor.
 */
function gutenberg_site_editor_wp_admin_prepare_screen() {
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Only picks the highlighted menu item.
	$path    = isset( $_GET['p'] ) && is_string( $_GET['p'] ) ? sanitize_text_field( wp_unslash( $_GET['p'] ) ) : '/';
	$section = gutenberg_get_site_editor_wp_admin_section_for_path( $path );

	add_filter(
		'submenu_file',
		static function () use ( $section ) {
			return $section
				? gutenberg_get_site_editor_wp_admin_url( $section['to'] )
				: 'site-editor-v2-wp-admin';
		}
	);
}

add_action( 'site-editor-v2-wp-admin_init', '_gutenberg_preload_route_entity_fields' );

/**
 * Returns the route path matching a site-editor.php URL.
 *
 * Handles the `p` paths of the site editor, and the older `postType`,
 * `postId` and `path` args that Core still links to, such as the "Edit site"
 * link in the admin bar. Unknown URLs map to the home route.
 *
 * @param array $args Query args of the site-editor.php URL.
 * @return string The route path.
 */
function gutenberg_get_site_editor_wp_admin_path_for_site_editor_args( $args ) {
	$list_paths = array(
		'wp_template'      => '/templates',
		'wp_template_part' => '/template-parts',
		'wp_block'         => '/patterns',
		'page'             => '/types/page',
		'wp_navigation'    => '/navigation',
	);

	$post_type = isset( $args['postType'] ) ? (string) $args['postType'] : '';
	$post_id   = isset( $args['postId'] ) ? (string) $args['postId'] : '';

	if ( ! empty( $args['p'] ) ) {
		$p = '/' . trim( (string) $args['p'], '/' );

		// List paths, such as `/template` or `/pattern`. The template parts
		// list is `/pattern` with a `postType` arg.
		$v1_lists = array(
			'/template'   => 'wp_template',
			'/pattern'    => 'wp_template_part' === $post_type ? 'wp_template_part' : 'wp_block',
			'/page'       => 'page',
			'/navigation' => 'wp_navigation',
		);
		if ( isset( $v1_lists[ $p ] ) ) {
			return $list_paths[ $v1_lists[ $p ] ];
		}
		if ( in_array( $p, array( '/styles', '/stylebook' ), true ) ) {
			return '/styles';
		}
		if ( '/identity' === $p ) {
			return '/identity';
		}

		// Item paths, such as `/wp_template/twentytwentyfive//home`.
		$parts     = explode( '/', ltrim( $p, '/' ), 2 );
		$post_type = $parts[0];
		$post_id   = $parts[1] ?? '';
		if ( '' === $post_id || ! isset( $list_paths[ $post_type ] ) ) {
			return '/';
		}
	} elseif ( ! empty( $args['path'] ) ) {
		$legacy_paths = array(
			'/wp_global_styles'     => '/styles',
			'/wp_template/all'      => '/templates',
			'/wp_template_part/all' => '/template-parts',
			'/patterns'             => '/patterns',
			'/navigation'           => '/navigation',
		);
		return $legacy_paths[ (string) $args['path'] ] ?? '/';
	}

	if ( ! isset( $list_paths[ $post_type ] ) ) {
		return '/';
	}
	if ( '' === $post_id ) {
		return $list_paths[ $post_type ];
	}
	if ( 'wp_navigation' === $post_type ) {
		return '/navigation/edit/' . rawurlencode( $post_id );
	}
	return '/types/' . $post_type . '/edit/' . rawurlencode( $post_id );
}

/**
 * Redirects site-editor.php to the matching route of the site editor page.
 *
 * Core and plugins link to site-editor.php in several places, such as the
 * "Edit site" link in the admin bar and the Themes screen.
 */
function gutenberg_redirect_site_editor_to_site_editor_wp_admin() {
	// Theme previews are handled by site-editor.php or the theme preview page.
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended
	if ( isset( $_GET['wp_theme_preview'] ) ) {
		return;
	}

	// The page is only registered when the theme supports the site editor.
	if ( '' === menu_page_url( 'site-editor-v2-wp-admin', false ) ) {
		return;
	}

	$args = array();
	foreach ( array( 'p', 'path', 'postType', 'postId' ) as $key ) {
		// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Only picks the route to open.
		if ( isset( $_GET[ $key ] ) && is_string( $_GET[ $key ] ) ) {
			// phpcs:ignore WordPress.Security.NonceVerification.Recommended
			$args[ $key ] = sanitize_text_field( wp_unslash( $_GET[ $key ] ) );
		}
	}

	$path = gutenberg_get_site_editor_wp_admin_path_for_site_editor_args( $args );
	$url  = admin_url( 'themes.php?page=site-editor-v2-wp-admin' );
	if ( '/' !== $path ) {
		$url = add_query_arg( 'p', rawurlencode( $path ), $url );
	}

	wp_safe_redirect( $url );
	exit;
}
add_action( 'load-site-editor.php', 'gutenberg_redirect_site_editor_to_site_editor_wp_admin' );
